import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes — 2023","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-2023.md","filePath":"aireblock-releases/AireFrame/aireframe-2023.md","lastUpdated":1786968286000}`),a={name:`aireblock-releases/AireFrame/aireframe-2023.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes-—-2023" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes — 2023</span> <a class="header-anchor" href="#aireframe-release-notes-—-2023" aria-label="Permalink to “AireFrame Release Notes — 2023”">​</a></h1><p>This page contains the AireFrame releases published during 2023.</p><h2 id="version-2-3-0-—-wcag-2-2-subject-access-configuration" tabindex="-1">Version 2.3.0 — WCAG 2.2 &amp; Subject Access Configuration <a class="header-anchor" href="#version-2-3-0-—-wcag-2-2-subject-access-configuration" aria-label="Permalink to “Version 2.3.0 — WCAG 2.2 &amp; Subject Access Configuration”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 29, 2023</p></blockquote><h3 id="♿-accessibility" tabindex="-1">♿ Accessibility <a class="header-anchor" href="#♿-accessibility" aria-label="Permalink to “♿ Accessibility”">​</a></h3><ul><li>Ensure all components meet WCAG 2.2 standards</li></ul><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add <code>plus_time</code> and <code>round_to_next</code> Liquid filters</li><li>Add ability to define the subject access configuration</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>AireForms now correctly looks up the author when displaying a form</li></ul><h2 id="version-2-2-0-—-visualisation-notification-improvements" tabindex="-1">Version 2.2.0 — Visualisation &amp; Notification Improvements <a class="header-anchor" href="#version-2-2-0-—-visualisation-notification-improvements" aria-label="Permalink to “Version 2.2.0 — Visualisation &amp; Notification Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 20, 2023</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Upgrade Monaco editor to latest</li><li>Improve frontend visualisation performance</li><li>Add success message on PDF upload</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix visualisation errors</li><li>Fix issue where notifications were not always being received</li></ul><h2 id="version-2-1-0-—-visualisation-data-caching" tabindex="-1">Version 2.1.0 — Visualisation Data Caching <a class="header-anchor" href="#version-2-1-0-—-visualisation-data-caching" aria-label="Permalink to “Version 2.1.0 — Visualisation Data Caching”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 8, 2023</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add caching support for subject-based visualisations on the single subject view and subject list</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve paging performance</li></ul><h2 id="version-2-0-0-—-performance-improvements" tabindex="-1">Version 2.0.0 — Performance Improvements <a class="header-anchor" href="#version-2-0-0-—-performance-improvements" aria-label="Permalink to “Version 2.0.0 — Performance Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 18, 2023</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Visualisation data now uses primitive values rather than strings</li><li>Migrate to the AireForms V2 Extract API</li><li>Fetch subjects as a batch rather than individually</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix default location update error</li><li>Fix issue where visualisations would fail to load if the user did not have the view subject record item permission</li></ul><h3 id="⚠️-breaking-configuration-changes" tabindex="-1">⚠️ Breaking / Configuration Changes <a class="header-anchor" href="#⚠️-breaking-configuration-changes" aria-label="Permalink to “⚠️ Breaking / Configuration Changes”">​</a></h3><ul><li>Disallow date/time filters (<code>date</code>, <code>cui_date</code>, <code>cui_time</code>, <code>cui_date_time</code>) in mapping and filter transforms; these must be applied as a series formatter instead</li></ul><h2 id="version-1-39-0-—-search-location-improvements" tabindex="-1">Version 1.39.0 — Search &amp; Location Improvements <a class="header-anchor" href="#version-1-39-0-—-search-location-improvements" aria-label="Permalink to “Version 1.39.0 — Search &amp; Location Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 4, 2023</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add search filter to data visualisations</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Last selected location now persists across browsers</li><li>Move change location to a popover rather than a modal</li><li>Create form permission is now split from upload PDF (create subject record item)</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix initial configuration import failure</li></ul><h2 id="version-1-38-0-—-ux-improvements" tabindex="-1">Version 1.38.0 — UX Improvements <a class="header-anchor" href="#version-1-38-0-—-ux-improvements" aria-label="Permalink to “Version 1.38.0 — UX Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 23, 2023</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Allow support for importing and exporting custom data sources</li><li>Add ability to delete a data source instance</li><li>Add tenant-level toggle to show the user role in the menu bar</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Migrate custom data source client secret to be an AireVault secret</li><li>Show page number and total pages on paged lists</li><li>Improve structural entity selector placement and scroll behaviour</li><li>Use git sparse checkout for faster repository sync</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where a success message was shown to a user if git push failed</li></ul><h2 id="version-1-37-0-—-git-backed-configuration-transfer" tabindex="-1">Version 1.37.0 — Git-Backed Configuration Transfer <a class="header-anchor" href="#version-1-37-0-—-git-backed-configuration-transfer" aria-label="Permalink to “Version 1.37.0 — Git-Backed Configuration Transfer”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 8, 2023</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to export/import configuration to/from a configured git repository</li></ul><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Rename data extracts to data sets</li><li>Allow location selector items to be collapsed</li><li>Improve styling of popovers</li><li>Prevent widget title from wrapping and causing layout issues</li><li>Improve error message shown when no subject input field is marked as required</li></ul><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where the data point formatter does not take into account the series data type</li></ul><h2 id="version-1-36-0-—-configuration-ui-fixes" tabindex="-1">Version 1.36.0 — Configuration &amp; UI Fixes <a class="header-anchor" href="#version-1-36-0-—-configuration-ui-fixes" aria-label="Permalink to “Version 1.36.0 — Configuration &amp; UI Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 21, 2023</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Lock changing the subject provider by default so consequences of changing are clearer</li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix location selector when scrolling</li><li>Fix issue where export configuration order was not predictable</li><li>Fix issue where bar graph could not be edited</li></ul><h2 id="version-1-35-0-—-ui-improvements" tabindex="-1">Version 1.35.0 — UI Improvements <a class="header-anchor" href="#version-1-35-0-—-ui-improvements" aria-label="Permalink to “Version 1.35.0 — UI Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 30, 2023</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved dashboard location selector UI</li><li>Move data sources into visualisation configuration section</li><li>Add support for span tags with custom styling in the Liquid editor</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where new data source keys were set to a UUID instead of the entered key</li></ul><h2 id="version-1-34-0-—-default-dashboards" tabindex="-1">Version 1.34.0 — Default Dashboards <a class="header-anchor" href="#version-1-34-0-—-default-dashboards" aria-label="Permalink to “Version 1.34.0 — Default Dashboards”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 21, 2023</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Specify a default dashboard for each section</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Rename collections to dashboards</li><li>Rename views to sections</li><li>Improve viewing audit performance</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where the subject list would not respect widget ordering in a dashboard</li><li>Fix issue where subject search would not return expected results when values contained a space</li><li>Fix issue where bar charts would cause overlapping at the extreme ends of the axis</li><li>Fix issue where form buttons were not shown correctly</li></ul><h2 id="version-1-33-0-—-visualisation-metadata-improvements" tabindex="-1">Version 1.33.0 — Visualisation Metadata Improvements <a class="header-anchor" href="#version-1-33-0-—-visualisation-metadata-improvements" aria-label="Permalink to “Version 1.33.0 — Visualisation Metadata Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 2, 2023</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for a read-only replica connection string for all read queries</li><li>Populate visualisation time frame picker when a default time frame is defined</li><li>Add support for providing structural entity key on subject location mutations instead of the ID</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Restrict date/time based charts to only allow chronological order</li><li>Prefix and suffix whitespace is now ignored when calculating the output type of a Liquid expression in the pipeline</li><li>Improved error handling when there is an issue loading a chart</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where notifications were not being received</li></ul><h2 id="version-1-32-0-—-subject-fields-extract" tabindex="-1">Version 1.32.0 — Subject Fields Extract <a class="header-anchor" href="#version-1-32-0-—-subject-fields-extract" aria-label="Permalink to “Version 1.32.0 — Subject Fields Extract”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 19, 2023</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to create a data extract for subject fields from the internal store</li><li>Support <code>assign</code> in pipeline Liquid expressions</li><li>Ability to configure reference values for series on the y-axis</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Collections are now ordered alphabetically</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where removing a field from earlier in the pipeline made it impossible to alter later stages</li><li>Fix issue where selected visualisation type was not highlighted in the designer</li></ul><h2 id="version-1-31-0-—-series-liquid-formatting" tabindex="-1">Version 1.31.0 — Series Liquid Formatting <a class="header-anchor" href="#version-1-31-0-—-series-liquid-formatting" aria-label="Permalink to “Version 1.31.0 — Series Liquid Formatting”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 12, 2023</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Support a Liquid expression for formatting the series display values</li></ul><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Update Internal Store to reference keys rather than IDs</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where multiple data visualisations could be created with the same key within a tenant</li></ul><h2 id="version-1-30-0-—-pipeline-improvements" tabindex="-1">Version 1.30.0 — Pipeline Improvements <a class="header-anchor" href="#version-1-30-0-—-pipeline-improvements" aria-label="Permalink to “Version 1.30.0 — Pipeline Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 5, 2023</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add ability to configure group by in the visualisation pipeline</li><li>Add custom age Liquid filter</li><li>Add ability to filter AireFlow tasks by workflow key and task key</li></ul><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Normalise count transform to be a literal count rather than group and count</li><li>Improve Liquid editor suggestions</li><li>Ensure tooltip is always shown on visualisation type selector</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where the default ordering could reference a series that had been removed</li></ul><h2 id="version-1-29-0-—-single-number-visualisation" tabindex="-1">Version 1.29.0 — Single Number Visualisation <a class="header-anchor" href="#version-1-29-0-—-single-number-visualisation" aria-label="Permalink to “Version 1.29.0 — Single Number Visualisation”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 2, 2023</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add single number visualisation</li><li>Add ability to configure a default time frame in the new designer</li><li>Add dialog box asking if the user wants to open a form upon receiving a notification</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where multiple choice field options were not exported and imported</li><li>Handle tenant not existing in AireFlow more gracefully</li></ul><h2 id="version-1-28-0-—-configuration-keys-ui-improvements" tabindex="-1">Version 1.28.0 — Configuration Keys &amp; UI Improvements <a class="header-anchor" href="#version-1-28-0-—-configuration-keys-ui-improvements" aria-label="Permalink to “Version 1.28.0 — Configuration Keys &amp; UI Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 19, 2023</p></blockquote><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add keys to data sources, visualisations and collections to enable import across the same environment</li></ul><h3 id="⚡-improvements-13" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-13" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Liquid editor is now shown in a popover so layout is not shifted when it is opened</li><li>Add a confirmation modal before deleting a visualisation</li><li>Better guidance when trying to modify or delete a custom field used in the unsolicited inbound configuration</li></ul><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where removing a collection from a view didn&#39;t remove it from user defaults for that view</li><li>Fix issue where the right-hand panel could not be shrunk easily when displaying an iframe</li></ul><h2 id="version-1-27-0-—-new-visualisation-designer" tabindex="-1">Version 1.27.0 — New Visualisation Designer <a class="header-anchor" href="#version-1-27-0-—-new-visualisation-designer" aria-label="Permalink to “Version 1.27.0 — New Visualisation Designer”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 5, 2023</p></blockquote><h3 id="✨-new-features-12" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-12" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add new visualisation designer with ability to define a data pipeline</li><li>Add Liquid editor via Monaco to provide autocompletion and syntax highlighting on computed fields, filters and mappers</li><li>Add keys to structure types, groups and data extracts to enable import across the same environment</li></ul><h3 id="⚡-improvements-14" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-14" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Remove roles from the configuration transfer</li><li>Send a notification to the user who triggered an import once it has completed</li></ul><h2 id="version-1-26-0-—-configuration-transfer" tabindex="-1">Version 1.26.0 — Configuration Transfer <a class="header-anchor" href="#version-1-26-0-—-configuration-transfer" aria-label="Permalink to “Version 1.26.0 — Configuration Transfer”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 15, 2023</p></blockquote><h3 id="✨-new-features-13" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-13" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add configuration transfer (export and import)</li><li>Add search filter on data extracts</li></ul><h3 id="⚡-improvements-15" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-15" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Change default click on subject list to open subject record</li><li>Add Ctrl+click on subject list to open subject preview</li><li>HTML tags now render on subject search results</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where widgets on collection configurator kept re-ordering</li><li>Fix issue where actions needed to be opened twice to show after completing an action</li><li>Fix issue where it was impossible to add a data source if there was a connection error to any bundled data source</li><li>Fix issue where an incorrectly configured chart would error the entire page</li></ul><h2 id="version-1-25-0-—-list-collection-improvements" tabindex="-1">Version 1.25.0 — List &amp; Collection Improvements <a class="header-anchor" href="#version-1-25-0-—-list-collection-improvements" aria-label="Permalink to “Version 1.25.0 — List &amp; Collection Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 27, 2023</p></blockquote><h3 id="✨-new-features-14" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-14" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add pagination to visualisations list</li><li>Allow a collection to be used on multiple views</li></ul><h3 id="⚡-improvements-16" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-16" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve error message for subject being removed from the user&#39;s view</li><li>Force break in subject banner if no space exists in value</li><li>Inbound subject endpoint now returns 400 if not configured</li></ul><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix within-page ordering on paged lists</li><li>Fix issues on structure forms</li><li>Subject menu is no longer shown if subject not loaded</li></ul><h2 id="version-1-24-0-—-v2-charts" tabindex="-1">Version 1.24.0 — V2 Charts <a class="header-anchor" href="#version-1-24-0-—-v2-charts" aria-label="Permalink to “Version 1.24.0 — V2 Charts”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 16, 2023</p></blockquote><h3 id="✨-new-features-15" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-15" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Add support for ECharts Pie Charts</li><li>Add support for tables with Charts V2</li></ul><h3 id="⚡-improvements-17" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-17" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improve Tenant Initialisation</li><li>Improve access denied error messages</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix bug where subject field order could not be saved</li></ul><h2 id="version-1-23-0-—-apache-echarts" tabindex="-1">Version 1.23.0 — Apache ECharts <a class="header-anchor" href="#version-1-23-0-—-apache-echarts" aria-label="Permalink to “Version 1.23.0 — Apache ECharts”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 7, 2023</p></blockquote><h3 id="✨-new-features-16" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-16" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Use Apache ECharts for V2 Charts</li><li>Add feature toggle for V2 Charts</li><li>Add ability to pass location key on unsolicited inbound message</li></ul><h2 id="version-1-22-0-—-authentication-improvement" tabindex="-1">Version 1.22.0 — Authentication Improvement <a class="header-anchor" href="#version-1-22-0-—-authentication-improvement" aria-label="Permalink to “Version 1.22.0 — Authentication Improvement”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 19, 2023</p></blockquote><h3 id="⚡-improvements-18" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-18" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Remove use of <code>/userinfo</code> endpoint in the backend</li></ul><h2 id="version-1-21-0-—-collection-data-extract-improvements" tabindex="-1">Version 1.21.0 — Collection &amp; Data Extract Improvements <a class="header-anchor" href="#version-1-21-0-—-collection-data-extract-improvements" aria-label="Permalink to “Version 1.21.0 — Collection &amp; Data Extract Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 5, 2023</p></blockquote><h3 id="⚡-improvements-19" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-19" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Selected collections are now persisted between sessions and tenants</li><li>Allow DataExtract to be updated</li><li>Standardise form control error messages</li></ul><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix issue where structural entities would fail to load</li></ul>`,164)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};